    cin >> n;
    vector<vector<long long>> ranges(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ranges[i][j];
        }
    }

    sort(ranges.begin(), ranges.end(), [](const vector<long long>& x, const vector<long long>& y) {
        if (x[0] != y[0]) return x[0] < y[0];
        return x[1] > y[1];
    });
    long long count = 0, maxEnd = -1;
    for (const vector<long long>& r0 : ranges) {
        if (r0[1] > maxEnd) {
            count++;
            maxEnd = r0[1];
        }
    }
    cout << count << "\n";

    return 0;
